// githubSource.js — the PR-list and prStatus payload dialects must never
// drift apart again.
function _ghPrHeadRepoFull(pr) {
   var r = pr && pr.head && pr.head.repo;
   if (!r) return null;
   if (typeof r === 'string') return r.indexOf('/') !== -1 ? r : null;
   return _ghRepoShapeFull(r);
